actions.script:
import org.moqui.resource.ResourceReference
import groovy.util.Node

if (!artifactUri) return
ResourceReference rr = ec.resource.getLocationReference(artifactUri)

String targetVerb = ""
String targetNoun = ""
if (serviceName) {
    String cleanName = serviceName.trim()
    if (cleanName.contains("#")) {
        String[] parts = cleanName.split("#")
        targetNoun = parts[1]
        String left = parts[0]
        targetVerb = left.contains(".") ? left.split("\\.").last() : left
    } else if (cleanName.contains(".")) {
        targetVerb = cleanName.split("\\.").last()
    } else {
        targetVerb = cleanName
    }
}

def parseNodeToAst
parseNodeToAst = { Node n ->
    Map nodeMap = [
        name      : n.name()?.toString(),
        attributes: n.attributes() ?: [:],
        children  : []
    ]
    String txt = n.text()?.trim()
    if (txt) nodeMap.text = txt

    n.children().each { child ->
        if (child instanceof Node) {
            nodeMap.children.add(parseNodeToAst(child))
        }
    }
    return nodeMap
}

def createSkeletonServiceNode = { String v, String n ->
    return [
        name      : "service",
        attributes: [ verb: (v ?: "intake"), noun: (n ?: "NewResident") ],
        children  : [
            [ name: "in-parameters", attributes: [:], children: [] ],
            [ name: "out-parameters", attributes: [:], children: [] ],
            [ name: "actions", attributes: [:], children: [] ]
        ]
    ]
}

if (rr != null && rr.exists) {
    rawXmlContent = rr.getText()
    groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
    parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
    Node rootNode = parser.parseText(rawXmlContent)
    Map fileAst = parseNodeToAst(rootNode)

    isNewFile = false
    fullFileAst = fileAst

    Map matchedServiceNode = null
    if (targetVerb || targetNoun) {
        matchedServiceNode = (fileAst.children ?: []).find {
            it.name == 'service' && 
            it.attributes?.verb == targetVerb && 
            ((it.attributes?.noun ?: "") == targetNoun)
        }
    }

    if (!matchedServiceNode) {
        matchedServiceNode = createSkeletonServiceNode(targetVerb, targetNoun)
        fileAst.children.add(matchedServiceNode)
        isNewService = true
    } else {
        isNewService = false
    }

    serviceAst = matchedServiceNode
    return
}

// File does not exist on disk
Map newServiceNode = createSkeletonServiceNode(targetVerb, targetNoun)
fullFileAst = [
    name      : "services",
    attributes: [
        "xmlns:xsi": "http://www.w3.org/2001/XMLSchema-instance",
        "xsi:noNamespaceSchemaLocation": "http://moqui.org/xsd/service-definition-3.xsd"
    ],
    children  : [ newServiceNode ]
]
serviceAst = newServiceNode
isNewFile = true
isNewService = true
rawXmlContent = ""

import org.moqui.resource.ResourceReference
import groovy.xml.MarkupBuilder

String finalXml = rawXmlContent
if (!finalXml && serviceAst) {
    StringWriter writer = new StringWriter()
    MarkupBuilder xml = new MarkupBuilder(writer)

    def renderAstNode
    renderAstNode = { Map node, MarkupBuilder builder ->
        String tag = node.name ?: 'service'
        Map attrs = node.attributes ?: [:]
        List children = node.children ?: []

        if (children.isEmpty() && !node.text) {
            builder."${tag}"(attrs)
        } else if (children.isEmpty() && node.text) {
            builder."${tag}"(attrs, node.text)
        } else {
            builder."${tag}"(attrs) {
                children.each { child ->
                    if (child instanceof Map) renderAstNode(child, builder)
                }
            }
        }
    }

    renderAstNode(serviceAst, xml)
    finalXml = '<?xml version="1.0" encoding="UTF-8"?>\n' + writer.toString()
}

if (finalXml && artifactUri) {
    ResourceReference rr = ec.resource.getLocationReference(artifactUri)
    rr.putText(finalXml)
    status = "SUCCESS"
    message = "Service definition written to disk."
} else {
    status = "ERROR"
    message = "No XML or AST provided."
}

long start = System.currentTimeMillis()
boolean beganTx = false
Map inMap = testParameters ?: [:]

try {
    if (rollbackTransaction) {
        beganTx = ec.transaction.begin(60)
    }

    Map res = ec.service.sync().name(serviceName).parameters(inMap).call()
    results = res
    status = (res.containsKey("errorMessage") || res.containsKey("error")) ? "FAILURE" : "SUCCESS"

} catch (Throwable t) {
    status = "ERROR"
    errorMessage = t.getMessage() ?: t.toString()
    StringWriter sw = new StringWriter()
    t.printStackTrace(new PrintWriter(sw))
    errorStackTrace = sw.toString()
    ec.logger.warn("Test execution error on service [${serviceName}]: ${errorMessage}")
} finally {
    if (rollbackTransaction && beganTx) {
        try {
            ec.transaction.rollback(true, "Rollback transient test execution", null)
        } catch (Exception e) {
            ec.logger.warn("Error rolling back test transaction: ${e.message}")
        }
    }
    executionTimeMs = System.currentTimeMillis() - start
}

Map inParams = parameters ?: [:]
try {
    Map res = ec.service.sync().name(serviceName).parameters(inParams).call()
    context.results = res
    context.status = ec.message.hasError() ? "ERROR" : "SUCCESS"
    if (ec.message.hasError()) {
        context.errorMessage = ec.message.getErrorsString()
    }
} catch (Throwable t) {
    context.status = "ERROR"
    context.errorMessage = t.getMessage() ?: t.toString()
    ec.logger.error("❌ [run#Service] Error executing service [${serviceName}]: ${context.errorMessage}", t)
}
